create table ieos_stage1_test.reference_probe(id uuid);
-- Own scratch table so FK denial tests REFERENCES, not ALTER ownership.
-- This scratch-schema grant is disposable and rolls back with the whole suite.
grant create on schema ieos_stage1_test to authenticated;
alter table ieos_stage1_test.reference_probe owner to authenticated;
create function ieos_stage1_test.trigger_probe() returns trigger language plpgsql as 'begin return new; end';
grant execute on function ieos_stage1_test.trigger_probe() to anon,authenticated;
create function ieos_stage1_test.sqlstate_of(statement text) returns text language plpgsql security invoker set search_path='' as $$ begin begin execute statement; raise exception using errcode='PT001'; exception when sqlstate 'PT001' then return 'SUCCESS'; when others then return sqlstate; end; end $$;
grant execute on function ieos_stage1_test.sqlstate_of(text) to anon,authenticated;

reset role; set local role anon; select ieos_stage1_test.claim(null,'anon');
select extensions.is(ieos_stage1_test.sqlstate_of('truncate table public.knowledge_items'),'42501','ANON: TRUNCATE denied in public');
select extensions.is(ieos_stage1_test.sqlstate_of('create trigger p0_forbidden before insert on public.knowledge_items for each row execute function ieos_stage1_test.trigger_probe()'),'42501','ANON: TRIGGER creation denied in public');
select extensions.is(ieos_stage1_test.sqlstate_of('truncate table staging.knowledge_items'),'42501','ANON: TRUNCATE denied in staging');
